"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["84029"],{34621(e){e.exports=JSON.parse('{"id":"FIN-1001","slug":"continuous-compounding","term":"Continuous Compounding","also_known_as":[],"difficulty":"Intermediate","definition":"Continuous compounding is the theoretical limit of compounding interest more and more frequently, so that interest is added at every instant, producing the maximum possible growth for a given annual rate.","explanation":["Interest can be compounded yearly, monthly, daily or even more often. The more frequently it is compounded, the faster money grows, because interest starts earning interest sooner. Continuous compounding takes this to the limit.","For example, 1,000 invested at 5% a year grows to 1,050 with annual compounding and to about 1,051.16 with monthly compounding. With continuous compounding, it grows to about 1,051.27. The difference from daily compounding is tiny, which shows that the benefit of more frequent compounding levels off.","Continuous compounding uses the mathematical constant e, approximately 2.718. The value after a period is the starting amount multiplied by e raised to the power of the rate multiplied by the time.","In practice, banks rarely compound continuously, but the concept is widely used in finance because it simplifies calculations. It is used in option pricing models, such as Black\u2013Scholes, in calculating log returns and in valuing bonds and derivatives."],"note":"","total":1500,"prev":{"slug":"contingent-liability","term":"Contingent Liability"},"next":{"slug":"contract-asset","term":"Contract Asset"}}')}}]);